import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();
        if (paren_string == null) {
            return result;
        }

        // Remove all spaces from the input string
        String cleaned = paren_string.replace(" ", "");

        int balance = 0;
        int start = 0;

        for (int i = 0; i < cleaned.length(); i++) {
            char c = cleaned.charAt(i);
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
            }

            // When balance returns to 0, we have found a complete top-level group
            if (balance == 0 && i >= start) {
                // Only add if we actually encountered parentheses
                if (i >= start) {
                    result.add(cleaned.substring(start, i + 1));
                }
                start = i + 1;
            }
        }

        return result;
    }
}
