class Solution {
    /**
    Test if given string is a palindrome
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    public String makePalindrome(String string) {
        if (string == null || string.length() == 0) {
            return "";
        }

        int beginning_of_suffix = 0;

        // Find the longest postfix that is a palindrome
        // We check substrings starting from index 0, 1, 2... until the remaining suffix is a palindrome
        while (beginning_of_suffix < string.length() && !isPalindrome(string.substring(beginning_of_suffix))) {
            beginning_of_suffix++;
        }

        // The prefix that comes before the palindromic suffix
        String prefix = string.substring(0, beginning_of_suffix);

        // Append the reverse of that prefix to the original string
        return string + new StringBuilder(prefix).reverse().toString();
    }
}
