public class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return "";
        }

        int n = string.length();
        int longestPalindromePostfixLength = 0;

        // Find the longest postfix that is a palindrome
        for (int i = 0; i < n; i++) {
            if (isPalindrome(string, i, n - 1)) {
                longestPalindromePostfixLength = n - i;
                break;
            }
        }

        // The prefix that comes before the palindromic suffix
        String prefix = string.substring(0, n - longestPalindromePostfixLength);

        // Reverse the prefix
        StringBuilder sb = new StringBuilder(prefix);
        String reversedPrefix = sb.reverse().toString();

        // Append the reversed prefix to the original string
        return string + reversedPrefix;
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}
