public class Solution {
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return "";
        }

        // Map to associate word numerals with their integer values
        Map<String, Integer> numberMap = new HashMap<>();
        numberMap.put("zero", 0);
        numberMap.put("one", 1);
        numberMap.put("two", 2);
        numberMap.put("three", 3);
        numberMap.put("four", 4);
        numberMap.put("five", 5);
        numberMap.put("six", 6);
        numberMap.put("seven", 7);
        numberMap.put("eight", 8);
        numberMap.put("nine", 9);

        // Split the input string into an array of words
        String[] words = numbers.split("\\s+");

        // Sort the words based on their mapped integer values
        Arrays.sort(words, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return numberMap.get(a).compareTo(numberMap.get(b));
            }
        });

        // Join the sorted words back into a space-delimited string
        return String.join(" ", words);
    }
}
