class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        List<Double> closestPair = new ArrayList<>();
        closestPair.add(numbers.get(0));
        closestPair.add(numbers.get(1));
        double minDistance = Math.abs(numbers.get(1) - numbers.get(0));

        for (int i = 0; i < numbers.size(); i++) {
            for (int j = i + 1; j < numbers.size(); j++) {
                double currentDistance = Math.abs(numbers.get(i) - numbers.get(j));
                if (currentDistance < minDistance) {
                    minDistance = currentDistance;
                    closestPair.clear();
                    closestPair.add(numbers.get(i));
                    closestPair.add(numbers.get(j));
                }
            }
        }
        Collections.sort(closestPair);
        return closestPair;
    }
}
