class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Sort the list to ensure that the closest elements are adjacent
        List<Double> sortedList = new ArrayList<>(numbers);
        Collections.sort(sortedList);

        double minDiff = Double.MAX_VALUE;
        Double first = null;
        Double second = null;

        for (int i = 0; i < sortedList.size() - 1; i++) {
            double current = sortedList.get(i);
            double next = sortedList.get(i + 1);
            double diff = next - current;

            if (diff < minDiff) {
                minDiff = diff;
                first = current;
                second = next;
            }
        }

        return Arrays.asList(first, second);
    }
}
