class Solution {
    public int largestDivisor(int n) {
        for (int i = (int) Math.sqrt(n); i >= 1; i--) {
            if (n % i == 0) {
                // The largest divisor smaller than n is n divided by the smallest divisor greater than 1.
                // However, iterating downwards from sqrt(n) allows us to find the pair.
                // If i is a divisor, n/i is also a divisor.
                // We want the largest divisor < n, which is n / (smallest divisor > 1).
                // A simpler approach: find the smallest prime factor p, then n/p is the largest divisor.
            }
        }

        // Optimized approach: find the smallest divisor > 1
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no divisor found, n is prime, so the largest divisor smaller than n is 1
        return 1;
    }
}
