        double max = Collections.max(numbers);
        double range = max - min;

        // Handle case where all elements are the same to avoid division by zero
        if (range == 0) {
            return numbers.stream()
                          .map(n -> 0.0)
                          .collect(Collectors.toList());
        }

        return numbers.stream()
                      .map(n -> (n - min) / range)
