import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    public double findZero(List<Double> xs) {
        double begin = -1.0, end = 1.0;

        // Expand the range until we find a sign change (Intermediate Value Theorem)
        // Since the polynomial has an even number of coefficients, it is of odd degree.
        // Odd degree polynomials always have at least one real root.
        while (poly(xs, begin) * poly(xs, end) > 0) {
            begin *= 2;
            end *= 2;
        }

        // Binary search for the root
        // Ensure begin is the smaller value for the loop condition
        double low = Math.min(begin, end);
        double high = Math.max(begin, end);

        while (high - low > 1e-12) {
            double mid = (low + high) / 2;
            if (poly(xs, low) * poly(xs, mid) <= 0) {
                high = mid;
            } else {
                low = mid;
            }
        }
        return low;
    }
}
