class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the list to avoid modifying the original input if it's immutable
        List<Integer> result = new ArrayList<>(l);
        List<Integer> thirds = new ArrayList<>();

        // Collect elements at indices divisible by 3
        for (int i = 0; i < l.size(); i += 3) {
            thirds.add(l.get(i));
        }

        // Sort the collected elements
        Collections.sort(thirds);

        // Place the sorted elements back into the indices divisible by 3
        for (int i = 0; i < l.size(); i += 3) {
            result.set(i, thirds.get(i / 3));
        }

        return result;
    }
}
