import java.util.*;

public class Solution {
    /**
     * Finds a root of a polynomial given its coefficients.
     * The polynomial is defined as f(x) = xs[0] + xs[1]*x + xs[2]*x^2 + ...
     * Since the number of coefficients is even, the degree is odd, 
     * guaranteeing at least one real root.
     */
    public double findZero(List<Double> xs) {
        // Bisection method requires an interval [a, b] where f(a) and f(b) have opposite signs.
        // For an odd degree polynomial, as x -> infinity, f(x) follows the sign of the leading coefficient.
        // As x -> -infinity, f(x) follows the opposite sign of the leading coefficient.

        double low = -1.0;
        double high = 1.0;

        // Expand the range until we find a sign change
        while (evaluate(xs, low) * evaluate(xs, high) > 0) {
            low *= 2;
            high *= 2;
        }

        // Binary search (Bisection) for the root
        for (int i = 0; i < 100; i++) {
            double mid = (low + high) / 2.0;
            if (evaluate(xs, low) * evaluate(xs, mid) <= 0) {
                high = mid;
            } else {
                low = mid;
            }
        }

        return (low + high) / 2.0;
    }

    private double evaluate(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : xs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }
}
