    public List<Integer> sortEven(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            return l;
        }

        // Extract elements at even indices
        List<Integer> evens = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evens.add(l.get(i));
        }

        // Sort the extracted even-index elements
        Collections.sort(evens);

        // Create a new list to avoid modifying the original list in-place if it's immutable
        List<Integer> result = new ArrayList<>(l);

        // Place the sorted elements back into the even indices
        for (int i = 0, j = 0; i < result.size(); i += 2, j++) {
            result.set(i, evens.get(j));
        }

        return result;
    }
}
