import java.util.*;
import java.lang.*;

class Solution {
    public int primeFib(int n) {
        int f0 = 0;
        int f1 = 1;
        int count = 0;

        while (true) {
            int p = f0 + f1;

            // Check if p is prime
            boolean isPrime = true;
            if (p < 2) {
                isPrime = false;
            } else {
                for (int k = 2; k <= Math.sqrt(p); k++) {
                    if (p % k == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }

            if (isPrime) {
                count++;
                if (count == n) {
                    return p;
                }
            }

            f0 = f1;
            f1 = p;
        }
    }
}
