import java.util.*;

class Solution {
    public boolean triplesSumToZero(List<Integer> l) {
        if (l == null || l.size() < 3) {
            return false;
        }

        // Sort the list to use the two-pointer approach
        List<Integer> sortedList = new ArrayList<>(l);
        Collections.sort(sortedList);

        int n = sortedList.size();
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1;
            int right = n - 1;

            while (left < right) {
                int sum = sortedList.get(i) + sortedList.get(left) + sortedList.get(right);
                if (sum == 0) {
                    return true;
                } else if (sum < 0) {
                    left++;
                } else {
                    right--;
                }
            }
        }

        return false;
    }
}
