import java.util.*;

class Solution {
    public boolean pairsSumToZero(List<Integer> l) {
        if (l == null || l.size() < 2) {
            return false;
        }

        Set<Integer> seen = new HashSet<>();
        int zeroCount = 0;

        for (Integer num : l) {
            if (num == 0) {
                zeroCount++;
            } else {
                if (seen.contains(-num)) {
                    return true;
                }
                seen.add(num);
            }
        }

        // If there are at least two zeros, they sum to zero
        return zeroCount >= 2;
    }
}
