import java.util.*;
import java.lang.*;

class Solution {
    public double median(List<Integer> l) {
        // Create a copy of the list to avoid modifying the original input list
        List<Integer> sortedList = new ArrayList<>(l);
        Collections.sort(sortedList);

        int size = sortedList.size();
        if (size % 2 == 1) {
            // Odd number of elements: return the middle element
            return (double) sortedList.get(size / 2);
        } else {
            // Even number of elements: return the average of the two middle elements
            return (sortedList.get(size / 2 - 1) + sortedList.get(size / 2)) / 2.0;
        }
    }
}
