class Solution {
    /**
    returns encoded string by shifting every character by 5 in the alphabet.
     */
    public String encodeShift(String s) {
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            sb.append((char) ('a' + ((ch + 5 - 'a') % 26)));
        }
        return sb.toString();
    }

    /**
    returns decoded string by shifting every character back by 5 in the alphabet.
     */
    public String decodeShift(String s) {
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            // To reverse a shift of +5, we shift by -5.
            // In modulo 26, -5 is equivalent to +21.
            sb.append((char) ('a' + ((ch - 'a' + 21) % 26)));
        }
        return sb.toString();
    }
}
