class Solution {
    public int modp(int n, int p) {
        if (n == 0) {
            return 1 % p;
        }

        long res = 1;
        long base = 2 % p;
        int exp = n;

        while (exp > 0) {
            if (exp % 2 == 1) {
                res = (res * base) % p;
            }
            base = (base * base) % p;
            exp = exp / 2;
        }

        return (int) res;
    }
}
