     * 
     * @param n The exponent
     * @param p The modulus
     * @return (2^n) % p
     */
    public int modp(int n, int p) {
        if (p == 1) return 0;

        long res = 1;
        long base = 2 % p;
        long exp = n;

        while (exp > 0) {
            if (exp % 2 == 1) {
                res = (res * base) % p;
            }
            base = (base * base) % p;
            exp = exp / 2;
        }

        return (int) res;
    }
