class Solution {
    public int largestPrimeFactor(int n) {
        int largest = 1;
        int temp = n;

        // Divide out all 2s
        if (temp % 2 == 0) {
            largest = 2;
            while (temp % 2 == 0) {
                temp /= 2;
            }
        }

        // Divide out odd factors
        for (int i = 3; i * i <= temp; i += 2) {
            if (temp % i == 0) {
                largest = i;
                while (temp % i == 0) {
                    temp /= i;
                }
            }
        }

        // If temp is still > 1, the remaining temp is a prime factor
        if (temp > 1) {
            largest = temp;
        }

        return largest;
    }
}
