    public int largestPrimeFactor(int n) {
        int maxPrime = -1;

        // Remove factors of 2
        while (n % 2 == 0) {
            maxPrime = 2;
            n /= 2;
        }

        // Remove odd factors starting from 3
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
