public class Solution {
    public boolean correctBracketing(String brackets) {
        int balance = 0;
        for (int i = 0; i < brackets.length(); i++) {
            char c = brackets.charAt(i);
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
            }

            // If balance is negative, a closing bracket appeared without a preceding opening bracket
            if (balance < 0) {
                return false;
            }
        }
        // If balance is zero, all opening brackets were closed
        return balance == 0;
    }
}
