class Solution {
    public List<Integer> derivative(List<Integer> xs) {
        List<Integer> result = new ArrayList<>();
        // The derivative of a constant (xs[0]) is 0, so we start from index 1.
        // The derivative of xs[i] * x^i is (i * xs[i]) * x^(i-1).
        for (int i = 1; i < xs.size(); i++) {
            result.add(i * xs.get(i));
        }
        return result;
    }
