import java.util.*;
import java.lang.*;

class Solution {
    public String circularShift(int x, int shift) {
        String s = String.valueOf(x);
        int n = s.length();
        if (shift > n) {
            return new StringBuilder(s).reverse().toString();
        } else {
            // To shift right by 'shift', the last 'shift' characters move to the front
            // and the first 'n - shift' characters move to the back.
            String rightPart = s.substring(n - shift);
            String leftPart = s.substring(0, n - shift);
            return rightPart + leftPart;
        }
    }
}
