public class Solution {
    public String circularShift(int x, int shift) {
        String s = String.valueOf(x);
        int n = s.length();

        if (shift > n) {
            StringBuilder sb = new StringBuilder(s);
            return sb.reverse().toString();
        }

        int effectiveShift = shift % n;
        if (effectiveShift == 0) {
            return s;
        }

        // To shift right by 'effectiveShift', the last 'effectiveShift' characters 
        // move to the front, and the first 'n - effectiveShift' move to the back.
        String rightPart = s.substring(n - effectiveShift);
        String leftPart = s.substring(0, n - effectiveShift);

        return rightPart + leftPart;
    }
}
