import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> pluck(List<Integer> arr) {
        List<Integer> result = new ArrayList<>();
        if (arr == null || arr.isEmpty()) {
            return result;
        }

        int min = Integer.MAX_VALUE;
        int minIndex = -1;

        for (int i = 0; i < arr.size(); i++) {
            int current = arr.get(i);
            // Check if the number is even
            if (current % 2 == 0) {
                // We look for the smallest even value. 
                // Since we iterate from index 0 upwards, the first occurrence 
                // of the smallest value naturally satisfies the smallest index requirement.
                if (current < min) {
                    min = current;
                    minIndex = i;
                }
            }
        }

        if (minIndex != -1) {
            // The problem asks for [smallest_value, its_index]
            result.add(min);
            result.add(minIndex);
        }

        return result;
    }
}
