public class Solution {
    public List<Integer> pluck(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return new ArrayList<>();
        }

        Integer minEvenValue = null;
        int minIndex = -1;

        for (int i = 0; i < arr.size(); i++) {
            Integer current = arr.get(i);
            if (current != null && current % 2 == 0) {
                if (minEvenValue == null || current < minEvenValue) {
                    minEvenValue = current;
                    minIndex = i;
                }
                // If current == minEvenValue, we keep the one with the smaller index,
                // which is already stored since we are iterating from left to right.
            }
        }

        if (minEvenValue == null) {
            return new ArrayList<>();
        }

        List<Integer> result = new ArrayList<>();
        result.add(minEvenValue);
        result.add(minIndex);
        return result;
    }
}
