    public List<Integer> strangeSortList(List<Integer> lst) {
        List<Integer> res = new ArrayList<>();
        boolean _switch = true;
        List<Integer> l = new ArrayList<>(lst);
        while (l.size() != 0) {
            int value;
            if (_switch) {
                value = Collections.min(l);
            } else {
                value = Collections.max(l);
            }
            res.add(value);
            // Use remove(Object) to remove the first occurrence of the value, 
            // not the element at index 'value'.
            l.remove(Integer.valueOf(value));
            _switch = !_switch;
        }
        return res;
    }
}
