import java.util.*;

public class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        if (lst == null || lst.isEmpty()) {
            return new ArrayList<>();
        }

        // Create a copy to avoid modifying the original list and sort it
        List<Integer> sorted = new ArrayList<>(lst);
        Collections.sort(sorted);

        List<Integer> result = new ArrayList<>(lst.size());
        int left = 0;
        int right = sorted.size() - 1;
        boolean pickMin = true;

        while (left <= right) {
            if (pickMin) {
                result.add(sorted.get(left));
                left++;
            } else {
                result.add(sorted.get(right));
                right--;
            }
            pickMin = !pickMin;
        }

        return result;
    }
}
