class Solution {
    public int vowelsCount(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }

        String vowels = "aeiouAEIOU";
        int n_vowels = 0;
        char[] chars = s.toCharArray();

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            // Check if it is a standard vowel
            if (vowels.indexOf(c) != -1) {
                n_vowels++;
            } 
            // Check if it is 'y' or 'Y' and located at the end of the word
            else if ((c == 'y' || c == 'Y') && i == chars.length - 1) {
                n_vowels++;
            }
        }

        return n_vowels;
    }
}
