import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    /**
     * Calculates the number of mangoes in a basket given a string describing 
     * apples and oranges and the total count of all fruits.
     * 
     * @param s The string containing counts of apples and oranges.
     * @param n The total number of fruits in the basket.
     * @return The number of mangoes.
     */
    public int fruitDistribution(String s, int n) {
        int apples = 0;
        int oranges = 0;

        // Regex to find numbers preceding "apples" and "oranges"
        Pattern applePattern = Pattern.compile("(\\d+)\\s+apples");
        Pattern orangePattern = Pattern.compile("(\\d+)\\s+oranges");

        Matcher appleMatcher = applePattern.matcher(s);
        if (appleMatcher.find()) {
            apples = Integer.parseInt(appleMatcher.group(1));
        }

        Matcher orangeMatcher = orangePattern.matcher(s);
        if (orangeMatcher.find()) {
            oranges = Integer.parseInt(orangeMatcher.group(1));
        }

        return n - apples - oranges;
    }
}
