import java.util.*;
import java.lang.*;

class Solution {
    public boolean willItFly(List<Integer> q, int w) {
        // Check if the sum of elements is less than or equal to the maximum weight w
        int sum = 0;
        for (int val : q) {
            sum += val;
        }
        if (sum > w) {
            return false;
        }

        // Check if the list is palindromic (balanced)
        int i = 0, j = q.size() - 1;
        while (i < j) {
            if (!Objects.equals(q.get(i), q.get(j))) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}
