        // Check if the list is palindromic (balanced)
        int left = 0;
        int right = q.size() - 1;
        while (left < right) {
            if (!q.get(left).equals(q.get(right))) {
                return false;
            }
            left++;
            right--;
        }

        // Calculate the sum of elements
        long sum = 0;
        for (int weight : q) {
            sum += weight;
        }

        // Check if sum is less than or equal to maximum weight w
        return sum <= w;
    }
