     */
    public int smallestChange(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return 0;
        }

        int changes = 0;
        int left = 0;
        int right = arr.size() - 1;

        // Compare elements from both ends moving towards the center
        while (left < right) {
            // If the elements at symmetric positions are different, 
            // one of them must be changed to match the other.
            if (!arr.get(left).equals(arr.get(right))) {
                changes++;
            }
            left++;
            right--;
        }

        return changes;
    }
}
