                for (int j = 2; j < 100; j++) {
                    if (PrimeChecker.isPrime(j)) {
                        for (int k = 2; k < 100; k++) {
                            if (PrimeChecker.isPrime(k)) {
                                if (i * j * k == a) {
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
