import java.util.*;
import java.lang.*;

class Solution {
    public boolean isMultiplyPrime(int a) {
        class IsPrime {
            public static boolean is_prime(int n) {
                if (n < 2) return false;
                for (int j = 2; j * j <= n; j++) {
                    if (n % j == 0) {
                        return false;
                    }
                }
                return true;
            }
        }

        // Since a < 100, the prime factors must be less than 100.
        // We iterate through all combinations of three primes.
        for (int i = 2; i < 100; i++) {
            if (!IsPrime.is_prime(i)) {
                continue;
            }
            for (int j = i; j < 100; j++) {
                if (!IsPrime.is_prime(j)) {
                    continue;
                }
                for (int k = j; k < 100; k++) {
                    if (!IsPrime.is_prime(k)) {
                        continue;
                    }
                    if (i * j * k == a) {
                        return true;
                    }
                    // Optimization: if product exceeds a, break the innermost loop
                    if (i * j * k > a) {
                        break;
                    }
                }
            }
        }
        return false;
    }
}
