import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean isMultiplyPrime(int a) {
        if (a < 2) return false;

        List<Integer> factors = new ArrayList<>();
        int temp = a;

        // Trial division to find prime factors
        for (int i = 2; i * i <= temp; i++) {
            while (temp % i == 0) {
                factors.add(i);
                temp /= i;
            }
        }

        // If there is a remaining factor greater than 1, it is prime
        if (temp > 1) {
            factors.add(temp);
        }

        // The problem asks if the number is the multiplication of 3 prime numbers
        return factors.size() == 3;
    }
}
