public class Solution {
    public boolean isSimplePower(int x, int n) {
        // Case 1: x is 1. Any n^0 = 1.
        if (x == 1) {
            return true;
        }

        // Case 2: n is 1. 1^int is always 1. 
        // Since we already checked x == 1, if n == 1 and x != 1, it's false.
        if (n == 1) {
            return false;
        }

        // Case 3: n is 0. 0^int is 0 (for int > 0).
        if (n == 0) {
            return x == 0;
        }

        // Iteratively multiply n by itself until we reach or exceed x.
        long currentPower = n;
        while (currentPower <= x) {
            if (currentPower == x) {
                return true;
            }
            currentPower *= n;

            // Prevent infinite loop if n is -1 or 1 (though handled above)
            if (n == -1 && currentPower != x) {
                // -1^int is either 1 or -1.
                return x == 1 || x == -1;
            }
        }

        return false;
    }
}
