public class Solution {
    public boolean iscube(int a) {
        if (a == 0) {
            return true;
        }

        // Handle negative numbers by checking the cube of the absolute value
        int absA = Math.abs(a);

        // Calculate the cube root using Math.cbrt
        double root = Math.cbrt(absA);

        // Round the result to the nearest integer to handle floating point precision
        int roundedRoot = (int) Math.round(root);

        // Check if the cube of the rounded root equals the absolute value of a
        return (long) roundedRoot * roundedRoot * roundedRoot == absA;
    }
}
