     *
     * @param num A string representing a hexadecimal number.
     * @return The count of prime hexadecimal digits.
     */
    public int hexKey(String num) {
        if (num == null || num.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < num.length(); i++) {
            char c = num.charAt(i);
            // Check if the character is one of the prime hex digits: 2, 3, 5, 7, B, D
            if (c == '2' || c == '3' || c == '5' || c == '7' || c == 'B' || c == 'D') {
                count++;
            }
        }
        return count;
    }
