class Solution {
    public boolean isHappy(String s) {
        if (s == null || s.length() < 3) {
            return false;
        }

        for (int i = 0; i <= s.length() - 3; i++) {
            char c1 = s.charAt(i);
            char c2 = s.charAt(i + 1);
            char c3 = s.charAt(i + 2);

            // A string is happy if every 3 consecutive letters are distinct.
            // Therefore, it is NOT happy if any two of the three are the same.
            if (c1 == c2 || c1 == c3 || c2 == c3) {
                return false;
            }
        }
        return true;
    }
}
