public class Solution {
    /**
     * Returns the count of n-digit positive integers that start or end with 1.
     * 
     * Logic:
     * Total n-digit numbers = 9 * 10^(n-1)
     * Numbers starting with 1: 1 * 10^(n-1)
     * Numbers ending with 1: 9 * 10^(n-2) (for n > 1)
     * Numbers starting AND ending with 1: 1 * 10^(n-2) (for n > 1)
     * 
     * Using Inclusion-Exclusion Principle:
     * Count = (Starts with 1) + (Ends with 1) - (Starts and Ends with 1)
     * 
     * For n = 1:
     * Only the number '1' fits. Result = 1.
     * 
     * For n > 1:
     * Count = 10^(n-1) + 9 * 10^(n-2) - 10^(n-2)
     * Count = 10^(n-1) + 8 * 10^(n-2)
     */
    public int startsOneEnds(int n) {
        if (n <= 0) return 0;
        if (n == 1) return 1;

        int powerTenNMinus2 = (int) Math.pow(10, n - 2);
        int powerTenNMinus1 = (int) Math.pow(10, n - 1);

        return powerTenNMinus1 + (8 * powerTenNMinus2);
    }
}
