public class Solution {
    /**
     * Calculates the sum of the digits of N and returns that sum in binary format.
     * 
     * @param N positive integer
     * @return string representation of the sum of digits in binary
     */
    public String solve(int N) {
        int sum = 0;
        int temp = N;

        // Calculate the sum of digits of N
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }

        // Convert the resulting sum to a binary string
        return Integer.toBinaryString(sum);
    }
}
