        if (currentWord.length() > 0) {
            result.append(sortString(currentWord.toString()));
        }

        return result.toString();
    }

    private String sortString(String word) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        return new String(chars);
    }
