        for (int i = 0; i < lst.size(); i++) {
            List<Integer> currentRow = lst.get(i);
            // To sort coordinates of the row by columns in descending order,
            // we iterate through the columns (j) from the end to the beginning.
            for (int j = currentRow.size() - 1; j >= 0; j--) {
                // Use .equals() or check for null if the list contains Integer objects
                if (currentRow.get(j) != null && currentRow.get(j) == x) {
                    // The coordinate is [row, column]
                    result.add(Arrays.asList(i, j));
                }
            }
        }

        return result;
    }
