class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();

        if (lst == null) {
            return result;
        }

        for (int r = 0; r < lst.size(); r++) {
            List<Integer> row = lst.get(r);
            if (row == null) continue;

            // Collect all column indices where the value equals x for the current row
            List<Integer> cols = new ArrayList<>();
            for (int c = 0; c < row.size(); c++) {
                if (row.get(c) != null && row.get(c) == x) {
                    cols.add(c);
                }
            }

            // Sort column indices in descending order as per requirements
            Collections.sort(cols, Collections.reverseOrder());

            // Add the coordinates [row, col] to the final result list
            for (int c : cols) {
                List<Integer> coordinate = new ArrayList<>();
                coordinate.add(r);
                coordinate.add(c);
                result.add(coordinate);
            }
        }

        return result;
    }
}
