class Solution {
    public List<Integer> sortArray(List<Integer> array) {
        if (array == null || array.isEmpty()) {
            return new ArrayList<>(array == null ? Collections.emptyList() : array);
        }

        // Create a copy to avoid modifying the original array
        List<Integer> result = new ArrayList<>(array);

        // Calculate sum of first and last index values
        int sum = result.get(0) + result.get(result.size() - 1);

        if (sum % 2 != 0) {
            // Sum is odd: sort in ascending order
            Collections.sort(result);
        } else {
            // Sum is even: sort in descending order
            result.sort(Collections.reverseOrder());
        }

        return result;
    }
}
