class Solution {
    public Optional<Integer> nextSmallest(List<Integer> lst) {
        if (lst == null || lst.isEmpty()) {
            return Optional.empty();
        }

        // Use a Set to remove duplicates, as the 2nd smallest must be distinct from the 1st
        Set<Integer> set = new HashSet<>(lst);
        List<Integer> sortedList = new ArrayList<>(set);
        Collections.sort(sortedList);

        // If there are fewer than 2 distinct elements, there is no 2nd smallest
        if (sortedList.size() < 2) {
            return Optional.empty();
        } else {
            return Optional.of(sortedList.get(1));
        }
    }
}
