class Solution {
    public int isBored(String S) {
        if (S == null || S.isEmpty()) {
            return 0;
        }

        // Split by sentence delimiters '.', '?', '!' and any following whitespace
        String[] sentences = S.split("[.?!]");
        int count = 0;

        for (String sentence : sentences) {
            // Trim leading whitespace to check if the sentence starts with "I"
            String trimmed = sentence.trim();
            if (!trimmed.isEmpty()) {
                // A boredom starts with the word "I". 
                // We check if it starts with "I" and is either just "I" or followed by a space.
                if (trimmed.equals("I") || trimmed.startsWith("I ")) {
                    count++;
                }
            }
        }
        return count;
    }
}
