import java.util.*;

class Solution {
    public Optional<Integer> nextSmallest(List<Integer> lst) {
        if (lst == null || lst.size() < 2) {
            return Optional.empty();
        }

        // Use a TreeSet to get unique elements in ascending order
        TreeSet<Integer> distinctSorted = new TreeSet<>(lst);

        // If there are fewer than 2 unique elements, there is no 2nd smallest
        if (distinctSorted.size() < 2) {
            return Optional.empty();
        }

        // The first element is the smallest, the second is the next smallest
        Iterator<Integer> it = distinctSorted.iterator();
        it.next(); // skip the smallest
        return Optional.of(it.next());
    }
}
