import java.util.*;
import java.lang.*;

class Solution {
    public int isBored(String S) {
        if (S == null || S.isEmpty()) {
            return 0;
        }

        // Split by sentence delimiters '.', '?', '!' and optional trailing whitespace
        String[] sentences = S.split("[.?!]\\s*");
        int count = 0;

        for (String sentence : sentences) {
            // Trim leading whitespace to ensure we check the start of the actual sentence
            String trimmed = sentence.trim();

            // A boredom starts with the word "I". 
            // It must be exactly "I" followed by a space, or just "I" if it's a one-word sentence.
            if (trimmed.equals("I") || trimmed.startsWith("I ")) {
                count++;
            }
        }
        return count;
    }
}
