class Solution {
    public int skjkasdkd(List<Integer> lst) {
        int maxPrime = -1;
        for (int i : lst) {
            if (i <= 1) continue;
            if (i > maxPrime) {
                if (isPrime(i)) {
                    maxPrime = i;
                }
            }
        }

        if (maxPrime == -1) return 0;

        int sum = 0;
        String s = String.valueOf(maxPrime);
        for (char c : s.toCharArray()) {
            sum += (c - '0');
        }
        return sum;
    }

    private boolean isPrime(int n) {
        if (n < 2) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }
}
