class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        boolean allUpper = true;
        boolean allLower = true;

        for (Object keyObj : dict.keySet()) {
            if (!(keyObj instanceof String)) {
                return false;
            }
            String key = (String) keyObj;

            // A key is considered "upper case" if it equals its own uppercase version
            // and "lower case" if it equals its own lowercase version.
            // However, the problem implies we check if the keys are consistently 
            // either all lower or all upper.
            if (!key.equals(key.toUpperCase())) {
                allLower = false;
            }
            if (!key.equals(key.toLowerCase())) {
                allUpper = false;
            }

            // If it's neither consistently all upper nor all lower across the set,
            // we can't satisfy the condition.
            if (!allUpper && !allLower) {
                return false;
            }
        }

        // The problem asks if ALL keys are lower OR ALL keys are upper.
        // Note: If keys are non-alphabetic (e.g., "123"), they are both upper and lower.
        return allUpper || allLower;
    }
}
