public class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        Set<Object> keys = dict.keySet();
        boolean allLower = true;
        boolean allUpper = true;

        for (Object key : keys) {
            if (!(key instanceof String)) {
                return false;
            }
            String s = (String) key;

            // A string is considered "lower case" if it equals its lowercase version
            // and "upper case" if it equals its uppercase version.
            if (!s.equals(s.toLowerCase())) {
                allLower = false;
            }
            if (!s.equals(s.toUpperCase())) {
                allUpper = false;
            }

            // Optimization: if both are already false, no need to check further
            if (!allLower && !allUpper) {
                return false;
            }
        }

        return allLower || allUpper;
    }
}
