class Solution {
    public String encode(String message) {
        String vowels = "aeiouAEIOU";
        StringBuilder sb = new StringBuilder();
        for (char c : message.toCharArray()) {
            char ch = c;
            if (Character.isUpperCase(ch)) {
                // Swap case to lower
                char lower = Character.toLowerCase(ch);
                // Check if the original character (or swapped) is a vowel
                if (vowels.indexOf(ch) != -1) {
                    // Replace vowel with letter 2 places ahead
                    // We use the swapped case for the result as per the "swap case" rule
                    ch = (char) ('a' + ((lower - 'a' + 2) % 26));
                } else {
                    ch = lower;
                }
            } else if (Character.isLowerCase(ch)) {
                // Swap case to upper
                char upper = Character.toUpperCase(ch);
                // Check if the original character (or swapped) is a vowel
                if (vowels.indexOf(ch) != -1) {
                    // Replace vowel with letter 2 places ahead
                    ch = (char) ('A' + ((upper - 'A' + 2) % 26));
                } else {
                    ch = upper;
                }
            } else {
                // For non-letter characters (like spaces), keep as is
                ch = c;
            }
            sb.append(ch);
        }
        return sb.toString();
    }
}
