import java.math.BigDecimal;
import java.math.RoundingMode;

class Solution {
    public int countUpper(String value) {
        // Use BigDecimal to handle precision and rounding modes accurately
        BigDecimal bd = new BigDecimal(value);

        // RoundingMode.HALF_UP rounds towards "nearest neighbor" 
        // and if equidistant, rounds up (towards positive infinity).
        // However, the requirement is "round away from zero".
        // BigDecimal.ROUND_HALF_UP in Java actually implements "half away from zero".
        // For example: 14.5 -> 15, -14.5 -> -15.
        return bd.setScale(0, RoundingMode.HALF_UP).intValue();
    }
}
