import java.util.*;
import java.lang.*;

class Solution {
    public int countUpper(String value) {
        double num = Double.parseDouble(value);

        // Math.round(double) in Java rounds to the nearest long.
        // If the value is equidistant (ends in .5), it rounds to positive infinity.
        // Example: Math.round(14.5) -> 15, Math.round(-14.5) -> -14.
        // The requirement is to round away from zero: -14.5 should become -15.

        if (num > 0) {
            return (int) Math.round(num);
        } else {
            // For negative numbers, if it ends in .5, Math.round goes towards zero.
            // We can handle this by rounding the absolute value and then negating.
            return (int) -Math.round(-num);
        }
    }
}
