import java.math.BigDecimal;
import java.math.RoundingMode;

public class Solution {
    public int countUpper(String value) {
        // Use BigDecimal to handle precision and specific rounding modes
        BigDecimal bd = new BigDecimal(value);

        // RoundingMode.HALF_UP rounds towards "nearest neighbor" 
        // unless both neighbors are equidistant, in which case it rounds up.
        // However, for negative numbers, HALF_UP rounds -14.5 to -14.
        // The requirement "round away from zero" corresponds to RoundingMode.HALF_UP 
        // for positive numbers and RoundingMode.HALF_DOWN for negative numbers.
        // Alternatively, RoundingMode.HALF_UP on the absolute value works, 
        // but Java's BigDecimal provides RoundingMode.HALF_UP which is "round half towards positive infinity".

        // To achieve "round half away from zero", we use RoundingMode.HALF_UP 
        // for positive and HALF_DOWN for negative, or simply use the signum.

        if (bd.signum() >= 0) {
            return bd.setScale(0, RoundingMode.HALF_UP).intValue();
        } else {
            return bd.setScale(0, RoundingMode.HALF_DOWN).intValue();
        }
    }
}
