import java.util.*;
import java.lang.*;

class Solution {
    public List<String> wordStrings(String s) {
        if (s == null || s.isEmpty()) {
            return new ArrayList<>();
        }

        // Split the string using a regular expression that matches one or more 
        // occurrences of either a comma or a whitespace character.
        String[] words = s.trim().split("[,\\s]+");

        // Filter out any empty strings that might result from leading/trailing delimiters
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (!word.isEmpty()) {
                result.add(word);
            }
        }

        return result;
    }
}
