class Solution {
    public int chooseNum(int x, int y) {
        if (x > y) {
            return -1;
        }
        if (y % 2 == 0) {
            return y;
        }
        // If y is odd, the largest even number is y - 1.
        // We must check if y - 1 is still within the range [x, y].
        if (y - 1 >= x) {
            return y - 1;
        }
        return -1;
    }
}
