import java.util.*;
import java.lang.*;

class Solution {
    public int chooseNum(int x, int y) {
        if (x > y) {
            return -1;
        }
        // The biggest even number in the range [x, y] is either y (if y is even)
        // or y - 1 (if y is odd).
        if (y % 2 == 0) {
            int result = y;
            return (result >= x) ? result : -1;
        } else {
            int result = y - 1;
            return (result >= x) ? result : -1;
        }
    }
}
