import java.util.*;
import java.lang.*;

class Solution {
    public List<String> wordStrings(String s) {
        if (s == null || s.trim().isEmpty()) {
            return new ArrayList<>();
        }

        // Replace commas with spaces to treat all delimiters uniformly
        StringBuilder sb = new StringBuilder();
        for (char letter : s.toCharArray()) {
            if (letter == ',') {
                sb.append(' ');
            } else {
                sb.append(letter);
            }
        }

        // Trim leading/trailing whitespace and split by one or more whitespace characters
        String processed = sb.toString().trim();
        if (processed.isEmpty()) {
            return new ArrayList<>();
        }

        return new ArrayList<>(Arrays.asList(processed.split("\\s+")));
    }
}
