class Solution {
    public List<Integer> makeAPile(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            // The first level is n.
            // Each subsequent level is the next odd/even number.
            // This means we increment by 2 for each level.
            result.add(n + 2 * i);
        }
        return result;
