import java.util.*;

public class Solution {
    public Object roundedAvg(int n, int m) {
        if (n > m) {
            return -1;
        }

        // The sum of integers from n to m is an arithmetic series:
        // Sum = (count * (first + last)) / 2
        // Average = Sum / count = (n + m) / 2.0
        double average = (n + m) / 2.0;

        // Round to the nearest integer. 
        // Math.round returns a long.
        long rounded = Math.round(average);

        // Convert the rounded integer to a binary string.
        return Long.toBinaryString(rounded);
    }
}
