import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    public int isBored(String S) {
        if (S == null || S.isEmpty()) {
            return 0;
        }

        // Split the string into sentences using '.', '?', or '!' as delimiters.
        // The regex [\.?!] matches any of these characters.
        String[] sentences = S.split("[.?!]");
        int count = 0;

        for (String sentence : sentences) {
            // Trim leading and trailing whitespace to find the first word
            String trimmed = sentence.trim();

            // Check if the sentence starts with the word "I"
            // It must be exactly "I" followed by a space or be the only word in the sentence.
            if (trimmed.equals("I") || trimmed.startsWith("I ")) {
                count++;
            }
        }

        return count;
    }
}
