            return new ArrayList<>();
        }

        // Map for digit to name conversion
        Map<Integer, String> digitMap = new HashMap<>();
        digitMap.put(1, "One");
        digitMap.put(2, "Two");
        digitMap.put(3, "Three");
        digitMap.put(4, "Four");
        digitMap.put(5, "Five");
        digitMap.put(6, "Six");
        digitMap.put(7, "Seven");
        digitMap.put(8, "Eight");
        digitMap.put(9, "Nine");

        // 1. Filter integers between 1 and 9 inclusive
        // 2. Sort them in ascending order
        // 3. Reverse the order (or sort descending)
        // 4. Map to their corresponding names
        return arr.stream()
                .filter(n -> n != null && n >= 1 && n <= 9)
                .sorted(Comparator.reverseOrder())
                .map(digitMap::get)
                .collect(Collectors.toList());
    }
}
