import java.util.*;

public class Solution {
    /**
     * Returns a list containing the count of even and odd integer palindromes
     * in the range [1, n].
     * 
     * @param n The upper bound of the range.
     * @return A list where index 0 is the count of even palindromes and index 1 is the count of odd palindromes.
     */
    public List<Integer> evenOddPalindrome(int n) {
        int evenCount = 0;
        int oddCount = 0;

        for (int i = 1; i <= n; i++) {
            if (isPalindrome(i)) {
                if (i % 2 == 0) {
                    evenCount++;
                } else {
                    oddCount++;
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        result.add(evenCount);
        result.add(oddCount);
        return result;
    }

    private boolean isPalindrome(int num) {
        int original = num;
        int reversed = 0;

        while (num > 0) {
            reversed = reversed * 10 + (num % 10);
            num /= 10;
        }

        return original == reversed;
    }
}
