class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            if (n == 0) continue;

            int temp = Math.abs(n);
            String s = String.valueOf(temp);
            int sum = 0;

            for (int i = 0; i < s.length(); i++) {
                int digit = s.charAt(i) - '0';
                if (i == 0 && n < 0) {
                    sum += -digit;
                } else {
                    sum += digit;
                }
            }

            if (sum > 0) {
                count++;
            }
        }
        return count;
    }
}
