import java.util.List;

public class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (Integer num : arr) {
            if (num == null) continue;
            if (sumOfDigits(num) > 0) {
                count++;
            }
        }
        return count;
    }

    private int sumOfDigits(int n) {
        String s = String.valueOf(n);
        int sum = 0;
        int start = 0;

        if (s.charAt(0) == '-') {
            // The first signed digit is negative
            // Extract the first digit after the '-' and make it negative
            int firstDigit = Character.getNumericValue(s.charAt(1));
            sum += -firstDigit;
            start = 2; // Start processing remaining digits from index 2
        } else {
            start = 0;
        }

        for (int i = start; i < s.length(); i++) {
            sum += Character.getNumericValue(s.charAt(i));
        }

        return sum;
    }
}
