import java.util.*;
import java.lang.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        if (arr == null || arr.size() == 0) {
            return true;
        }

        // Create a sorted version of the array to compare against
        List<Integer> sorted_arr = new ArrayList<>(arr);
        Collections.sort(sorted_arr);

        // Since elements are unique, the sorted array must start with the minimum value.
        // If the array can be sorted by right shifts, it must be a cyclic shift 
        // of the sorted array. We find the position of the minimum element 
        // and rotate the array to start from that index.
        int min_value = Collections.min(arr);
        int min_index = arr.indexOf(min_value);

        List<Integer> my_arr = new ArrayList<>();
        // Elements from min_index to the end
        my_arr.addAll(arr.subList(min_index, arr.size()));
        // Elements from the start to min_index
        my_arr.addAll(arr.subList(0, min_index));

        // Check if the rotated array matches the sorted array
        for (int i = 0; i < arr.size(); i++) {
            if (!my_arr.get(i).equals(sorted_arr.get(i))) {
                return false;
            }
        }

        return true;
    }
}
