import java.util.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return true;
        }

        int n = arr.size();
        if (n <= 1) {
            return true;
        }

        // A right-shifted sorted array of unique elements will have 
        // at most one point where the current element is greater than the next element.
        // If it has zero such points, it is already sorted.
        // If it has one such point, the last element must be smaller than the first element
        // to ensure that shifting the "tail" to the "head" maintains the sorted order.

        int dropCount = 0;
        int dropIndex = -1;

        for (int i = 0; i < n - 1; i++) {
            if (arr.get(i) > arr.get(i + 1)) {
                dropCount++;
                dropIndex = i;
            }
        }

        // Case 1: Already sorted
        if (dropCount == 0) {
            return true;
        }

        // Case 2: One drop point found. 
        // Check if the array is a rotated sorted array.
        // The last element must be less than or equal to the first element.
        if (dropCount == 1) {
            return arr.get(n - 1) <= arr.get(0);
        }

        // Case 3: More than one drop point means it can't be sorted by rotation.
        return false;
    }
}
