import java.util.*;
import java.lang.*;

class Solution {
    public String exchange(List<Integer> lst1, List<Integer> lst2) {
        int oddInLst1 = 0;
        for (int i : lst1) {
            if (i % 2 != 0) {
                oddInLst1 += 1;
            }
        }

        int evenInLst2 = 0;
        for (int i : lst2) {
            if (i % 2 == 0) {
                evenInLst2 += 1;
            }
        }

        // To make lst1 all even, we need to replace every odd number in lst1 
        // with an even number from lst2.
        if (evenInLst2 >= oddInLst1) {
            return "YES";
        }
        return "NO";
    }
}
