class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            int neg = 1;
            int tempN = n;
            if (tempN < 0) {
                tempN = -tempN;
                neg = -1;
            }

            List<Integer> digits = new ArrayList<>();
            String s = String.valueOf(tempN);
            for (char digit : s.toCharArray()) {
                digits.add(digit - '0');
            }

            if (!digits.isEmpty()) {
                digits.set(0, digits.get(0) * neg);
            }

            if (digits.stream().reduce(0, Integer::sum) > 0) {
                count += 1;
            }
        }
        return count;
    }
}
