class Solution {
    public List<Object> reverseDelete(String s, String c) {
        StringBuilder sb = new StringBuilder();
        // Iterate through s and append characters that are NOT present in c
        for (char ch : s.toCharArray()) {
            if (c.indexOf(ch) == -1) {
                sb.append(ch);
            }
        }

        String result = sb.toString();
        // Check if the result string is a palindrome
        String reversed = new StringBuilder(result).reverse().toString();
        boolean isPalindrome = result.equals(reversed);

        return Arrays.asList(result, isPalindrome);
    }
