import java.util.*;

public class Solution {
    public List<Object> reverseDelete(String s, String c) {
        // Create a set of characters to delete for O(1) lookup
        Set<Character> deleteSet = new HashSet<>();
        for (char ch : c.toCharArray()) {
            deleteSet.add(ch);
        }

        // Build the result string by filtering out characters in the deleteSet
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (!deleteSet.contains(ch)) {
                sb.append(ch);
            }
        }

        String resultString = sb.toString();

        // Check if the result string is a palindrome
        boolean isPalindrome = true;
        int left = 0;
        int right = resultString.length() - 1;
        while (left < right) {
            if (resultString.charAt(left) != resultString.charAt(right)) {
                isPalindrome = false;
                break;
            }
            left++;
            right--;
        }

        // Return as a list containing the result string and the boolean flag
        List<Object> result = new ArrayList<>();
        result.add(resultString);
        result.add(isPalindrome);

        return result;
    }
}
