class Solution {
    public int minSubArraySum(List<Integer> nums) {
        // Initialize minSum to the first element to handle cases where all numbers are positive
        int minSum = nums.get(0);
        int currentSum = 0;

        for (Integer num : nums) {
            currentSum += num;

            if (currentSum < minSum) {
                minSum = currentSum;
            }

            // If currentSum becomes positive, it cannot contribute to a smaller minimum sum
            // for subsequent sub-arrays, so we reset it to 0.
            if (currentSum > 0) {
                currentSum = 0;
            }
        }

        return minSum;
    }
}
