import java.util.*;
import java.lang.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return true;
        }

        int n = arr.size();
        int count = 0;

        // A right-shifted sorted array (with unique elements) will have 
        // at most one point where arr[i] > arr[i+1].
        // We check the wrap-around case (last element vs first element) as well.
        for (int i = 0; i < n; i++) {
            if (arr.get(i) > arr.get((i + 1) % n)) {
                count++;
            }
        }

        // If the array is sorted or a rotated version of a sorted array,
        // there will be at most one "drop" in value.
        return count <= 1;
    }
}
