import java.util.List;

public class Solution {
    /**
     * Finds the minimum sum of any non-empty sub-array of nums.
     * This is an implementation of Kadane's Algorithm modified to find the minimum sum.
     *
     * @param nums List of integers
     * @return The minimum sub-array sum
     */
    public int minSubArraySum(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be null or empty");
        }

        int minSoFar = nums.get(0);
        int currentMin = nums.get(0);

        for (int i = 1; i < nums.size(); i++) {
            int num = nums.get(i);
            // Either start a new sub-array at the current element or extend the existing minimum sub-array
            currentMin = Math.min(num, currentMin + num);
            // Update the global minimum found across all sub-arrays
            minSoFar = Math.min(minSoFar, currentMin);
        }

        return minSoFar;
    }
}
