import java.util.*;
import java.lang.*;

class Solution {
    public int maxFill(List<List<Integer>> grid, int capacity) {
        int totalLowerings = 0;
        for (List<Integer> row : grid) {
            int waterInWell = 0;
            for (int unit : row) {
                waterInWell += unit;
            }

            if (waterInWell > 0) {
                // Calculate ceiling of (waterInWell / capacity)
                // Using (a + b - 1) / b for integer ceiling division
                totalLowerings += (waterInWell + capacity - 1) / capacity;
            }
        }
        return totalLowerings;
    }
}
