import java.util.*;

class Solution {
    /**
     * Calculates the total number of times buckets must be lowered to empty all wells.
     * Each row in the grid represents a well. The number of 1s in a row is the amount of water.
     * Each well has its own bucket of a given capacity.
     * 
     * @param grid A rectangular grid where 1 represents a unit of water.
     * @param capacity The capacity of the bucket for each well.
     * @return The total number of bucket lowers required.
     */
    public int maxFill(List<List<Integer>> grid, int capacity) {
        int totalLowers = 0;
        for (List<Integer> row : grid) {
            int waterInWell = 0;
            for (Integer cell : row) {
                if (cell == 1) {
                    waterInWell++;
                }
            }

            // To empty a well, we need ceil(waterInWell / capacity)
            // Using integer arithmetic for ceiling: (a + b - 1) / b
            if (waterInWell > 0) {
                totalLowers += (waterInWell + capacity - 1) / capacity;
            }
        }
        return totalLowers;
    }
}
