class Solution {
    public List<String> selectWords(String s, int n) {
        List<String> result = new ArrayList<>();
        if (s == null || s.isEmpty()) {
            return result;
        }

        // Split by one or more spaces to handle potential multiple spaces
        String[] words = s.split("\\s+");

        for (String word : words) {
            if (word.isEmpty()) continue;

            int n_consonants = 0;
            for (char c : word.toCharArray()) {
                char lowerC = Character.toLowerCase(c);
                // Check if the character is a letter and NOT a vowel
                if (lowerC >= 'a' && lowerC <= 'z') {
                    if ("aeiou".indexOf(lowerC) == -1) {
                        n_consonants += 1;
                    }
                }
            }

            if (n_consonants == n) {
                result.add(word);
            }
        }
        return result;
    }
}
