class Solution {
    public String getClosestVowel(String word) {
        if (word == null || word.length() < 3) {
            return "";
        }

        String vowels = "aeiouAEIOU";
        // Start from the right side (second to last character)
        // and move towards the second character (index 1)
        for (int i = word.length() - 2; i > 0; i--) {
            char current = word.charAt(i);
            char prev = word.charAt(i - 1);
            char next = word.charAt(i + 1);

            // Check if current character is a vowel
            if (vowels.indexOf(current) != -1) {
                // Check if characters on both sides are consonants
                if (vowels.indexOf(prev) == -1 && vowels.indexOf(next) == -1) {
                    return String.valueOf(current);
                }
            }
        }
        return "";
    }
}
