import java.util.*;
import java.lang.*;

class Solution {
    public String matchParens(List<String> lst) {
        // There are only two possible concatenations: s1+s2 or s2+s1
        List<String> combinations = Arrays.asList(lst.get(0) + lst.get(1), lst.get(1) + lst.get(0));

        for (String s : combinations) {
            int balance = 0;
            boolean possible = true;
            for (char c : s.toCharArray()) {
                if (c == '(') {
                    balance++;
                } else {
                    balance--;
                }
                // If balance drops below 0, it's not a valid balanced parentheses string
                if (balance < 0) {
                    possible = false;
                    break;
                }
            }
            // A string is good if balance is exactly 0 at the end and never dropped below 0
            if (possible && balance == 0) {
                return "Yes";
            }
        }
        return "No";
    }
}
