import java.util.*;

public class Solution {
    public String matchParens(List<String> lst) {
        if (lst == null || lst.size() != 2) {
            return "No";
        }

        String s1 = lst.get(0);
        String s2 = lst.get(1);

        // Check both possible concatenation orders
        if (isBalanced(s1 + s2) || isBalanced(s2 + s1)) {
            return "Yes";
        }

        return "No";
    }

    private boolean isBalanced(String s) {
        int balance = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
            }

            // If balance goes negative, there are more closing than opening parens at this point
            if (balance < 0) {
                return false;
            }
        }
        // Final balance must be exactly 0 for the string to be balanced
        return balance == 0;
    }
}
