import java.util.*;

class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
        // Use a PriorityQueue as a min-heap to keep track of the k largest elements
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();

        for (int num : arr) {
            minHeap.offer(num);
            // If the heap size exceeds k, remove the smallest element
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        // Extract elements from the heap into a list
        List<Integer> result = new ArrayList<>(minHeap);
        // Sort the list in ascending order as required
        Collections.sort(result);

        return result;
    }
}
