class Solution {
    public List<Integer> getOddCollatz(int n) {
        List<Integer> odd_collatz = new ArrayList<>();
        long current = n; // Use long to prevent overflow during 3n + 1 calculation

        while (current != 1) {
            if (current % 2 != 0) {
                odd_collatz.add((int) current);
                current = 3 * current + 1;
            } else {
                current = current / 2;
            }
        }

        // The sequence always ends at 1, which is odd
        odd_collatz.add(1);

        Collections.sort(odd_collatz);
        return odd_collatz;
    }
}
