class Solution {
    public boolean validDate(String date) {
        if (date == null || date.isEmpty()) {
            return false;
        }

        try {
            // The format must be mm-dd-yyyy. 
            // Split by '-' and ensure there are exactly 3 parts.
            String[] parts = date.split("-");
            if (parts.length != 3) {
                return false;
            }

            // Validate that each part has the correct length to strictly follow mm-dd-yyyy
            if (parts[0].length() != 2 || parts[1].length() != 2 || parts[2].length() != 4) {
                return false;
            }

            int month = Integer.parseInt(parts[0]);
            int day = Integer.parseInt(parts[1]);
            int year = Integer.parseInt(parts[2]);

            // Rule 3: Months should not be less than 1 or higher than 12
            if (month < 1 || month > 12) {
                return false;
            }

            // Rule 2: Day validation based on month
            if (Arrays.asList(1, 3, 5, 7, 8, 10, 12).contains(month)) {
                if (day < 1 || day > 31) {
                    return false;
                }
            } else if (Arrays.asList(4, 6, 9, 11).contains(month)) {
                if (day < 1 || day > 30) {
                    return false;
                }
            } else if (month == 2) {
                if (day < 1 || day > 29) {
                    return false;
                }
            }

            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
