import java.util.*;
import java.lang.*;

class Solution {
    public Object splitWords(String txt) {
        if (txt.contains(" ")) {
            // Split on whitespace
            return Arrays.asList(txt.split("\\s+"));
        } else if (txt.contains(",")) {
            // Split on commas
            return Arrays.asList(txt.split(","));
        } else {
            // Count lower-case letters with odd order in the alphabet
            // ord('a') = 0, ord('b') = 1, ...
            int count = 0;
            for (char c : txt.toCharArray()) {
                if (Character.isLowerCase(c)) {
                    int order = c - 'a';
                    if (order % 2 != 0) {
                        count++;
                    }
                }
            }
            return count;
        }
    }
}
