public class Solution {
    public boolean validDate(String date) {
        if (date == null || date.isEmpty()) {
            return false;
        }

        // Rule 4: Check format mm-dd-yyyy using regex
        // This ensures we have exactly 2 digits, hyphen, 2 digits, hyphen, 4 digits
        if (!Pattern.matches("\\d{2}-\\d{2}-\\d{4}", date)) {
            return false;
        }

        // Split the date string into components
        String[] parts = date.split("-");
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        // Rule 3: Months should not be less than 1 or higher than 12
        if (month < 1 || month > 12) {
            return false;
        }

        // Rule 2: Validate days based on the month
        if (month == 2) {
            // February: 1 to 29
            if (day < 1 || day > 29) {
                return false;
            }
        } else if (month == 4 || month == 6 || month == 9 || month == 11) {
            // 30-day months
            if (day < 1 || day > 30) {
                return false;
            }
        } else {
            // 31-day months (1, 3, 5, 7, 8, 10, 12)
            if (day < 1 || day > 31) {
                return false;
            }
        }

        return true;
    }
}
