import java.util.*;

class Solution {
    public boolean isSorted(List<Integer> lst) {
        if (lst == null || lst.size() <= 1) {
            return true;
        }

        for (int i = 0; i < lst.size() - 1; i++) {
            // Check if the list is sorted in ascending order
            if (lst.get(i) > lst.get(i + 1)) {
                return false;
            }

            // Check for more than 1 duplicate (3 or more of the same number)
            // Since it's sorted, duplicates must be adjacent.
            // If current, next, and the one after are the same, return false.
            if (i < lst.size() - 2) {
                if (lst.get(i).equals(lst.get(i + 1)) && lst.get(i).equals(lst.get(i + 2))) {
                    return false;
                }
            }
        }

        return true;
    }
}
