import java.util.*;

public class Solution {
    public boolean isSorted(List<Integer> lst) {
        if (lst == null || lst.size() <= 1) {
            return true;
        }

        Map<Integer, Integer> counts = new HashMap<>();

        for (int i = 0; i < lst.size(); i++) {
            int current = lst.get(i);

            // Check if sorted in ascending order
            if (i > 0) {
                int previous = lst.get(i - 1);
                if (current < previous) {
                    return false;
                }
            }

            // Track occurrences to ensure no more than 1 duplicate (max 2 of same number)
            counts.put(current, counts.getOrDefault(current, 0) + 1);
            if (counts.get(current) > 2) {
                return false;
            }
        }

        return true;
    }
}
