class Solution {
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return Optional.empty();
        }

        int signProduct = 1;
        int sumMagnitudes = 0;

        for (Integer num : arr) {
            if (num == 0) {
                signProduct = 0;
            } else if (num < 0) {
                signProduct *= -1;
            }
            sumMagnitudes += Math.abs(num);
        }

        return Optional.of(signProduct * sumMagnitudes);
    }
}
