import java.util.*;
import java.lang.*;

class Solution {
    public String intersection(List<Integer> interval1, List<Integer> interval2) {
        // Find the boundaries of the intersection
        int l = Math.max(interval1.get(0), interval2.get(0));
        int r = Math.min(interval1.get(1), interval2.get(1));

        // If the intervals do not intersect, r < l
        if (r < l) {
            return "NO";
        }

        // The length of a closed interval [l, r] is r - l
        // Note: The problem example (2, 3) has length 1, which is 3 - 2.
        int length = r - l;

        if (isPrime(length)) {
            return "YES";
        } else {
            return "NO";
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }
        for (int i = 5; i * i <= n; i = i + 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
