import java.util.*;
import java.lang.*;

class Solution {
    public String intersection(List<Integer> interval1, List<Integer> interval2) {
        // The intersection of two closed intervals [a, b] and [c, d] 
        // is [max(a, c), min(b, d)].
        int l = Math.max(interval1.get(0), interval2.get(0));
        int r = Math.min(interval1.get(1), interval2.get(1));

        // If l > r, there is no intersection.
        if (l > r) {
            return "NO";
        }

        // The length of a closed interval [l, r] is r - l.
        // Note: The problem example (1, 3) and (2, 4) results in (2, 3) with length 1.
        int length = r - l;

        // Check if length is a prime number.
        if (isPrime(length)) {
            return "YES";
        } else {
            return "NO";
        }
    }

    private boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}
