import java.util.*;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        if (k == 0) return new ArrayList<>();

        // The goal is to find the lexicographically smallest path of length k.
        // To minimize the path lexicographically, we must start at the smallest possible value, which is 1.
        // Then, for the second element, we must move to the smallest possible neighbor of 1.
        // Once we reach the smallest neighbor (let's call it 'minNeighbor'), we can oscillate 
        // between 1 and 'minNeighbor' for the remainder of the path to keep the values as small as possible.
        // However, the path is [1, minNeighbor, 1, minNeighbor, ...].
        // Since 1 is the absolute minimum in the grid, any path starting with 1 is better than any other.
        // After the first step to minNeighbor, the best possible next step is back to 1.

        int startR = -1, startC = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    startR = i;
                    startC = j;
                    break;
                }
            }
            if (startR != -1) break;
        }

        if (k == 1) {
            return Collections.singletonList(1);
        }

        int minNeighbor = Integer.MAX_VALUE;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = startR + dr[i];
            int nc = startC + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                minNeighbor = Math.min(minNeighbor, grid.get(nr).get(nc));
            }
        }

        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans.add(1);
            } else {
                ans.add(minNeighbor);
            }
        }

        return ans;
    }
}
