import java.util.*;

public class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int minVal = Integer.MAX_VALUE;
        int startR = -1, startC = -1;

        // Step 1: Find the cell with the minimum value in the grid.
        // The lexicographically smallest path must start with the smallest possible value.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int val = grid.get(r).get(c);
                if (val < minVal) {
                    minVal = val;
                    startR = r;
                    startC = c;
                }
            }
        }

        // Step 2: Find the smallest neighbor of the minimum cell.
        // To make the path lexicographically smallest, we want the second element to be as small as possible.
        int minNeighbor = Integer.MAX_VALUE;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = startR + dr[i];
            int nc = startC + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                minNeighbor = Math.min(minNeighbor, grid.get(nr).get(nc));
            }
        }

        List<Integer> result = new ArrayList<>();

        // If k == 1, the path is just the minimum element.
        if (k == 1) {
            result.add(minVal);
            return result;
        }

        // If k > 1, the optimal strategy is to oscillate between the minimum element 
        // and its smallest neighbor.
        // Path: [min, minNeighbor, min, minNeighbor, ...]
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                result.add(minVal);
            } else {
                result.add(minNeighbor);
            }
        }

        return result;
    }
}
