import java.util.*;

public class Solution {
    public List<Integer> tri(int n) {
        List<Integer> result = new ArrayList<>();
        if (n < 0) return result;

        // The sequence is defined for n >= 1. 
        // Based on the example tri(3) = [1, 3, 2, 8], 
        // index 0 is 1, index 1 is 3, index 2 is 2, index 3 is 8.
        // This implies tri(0) = 1.

        int[] memo = new int[n + 1];
        Arrays.fill(memo, -1);

        // We need to solve for values from 0 to n.
        // The recurrence for odd n depends on tri(n+1).
        // This suggests we need to calculate values potentially beyond n.
        // However, for the specific range [0, n], we can determine the values.

        // Based on the rules:
        // tri(0) = 1 (from example)
        // tri(1) = 3
        // tri(even n) = 1 + n/2
        // tri(odd n) = tri(n-1) + tri(n-2) + tri(n+1)

        // Let's pre-calculate all even values up to n+1
        // and the base case tri(1).

        // To solve for tri(odd n), we need tri(n+1). Since n+1 is even, 
        // tri(n+1) is simply 1 + (n+1)/2.

        for (int i = 0; i <= n; i++) {
            result.add(calculateTri(i));
        }

        return result;
    }

    private int calculateTri(int i) {
        if (i == 0) return 1;
        if (i == 1) return 3;
        if (i % 2 == 0) {
            return 1 + (i / 2);
        } else {
            // tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
            // n is odd, so n-1 is even, n-2 is odd, n+1 is even.
            // This is a recursive definition. Let's expand:
            // tri(n) = (1 + (n-1)/2) + tri(n-2) + (1 + (n+1)/2)
            // tri(n) = tri(n-2) + 2 + (n-1+n+1)/2 = tri(n-2) + 2 + n

            // Base case for odd: tri(1) = 3
            // tri(3) = tri(1) + 2 + 3 = 3 + 5 = 8
            // tri(5) = tri(3) + 2 + 5 = 8 + 7 = 15

            int sum = 3; // tri(1)
            for (int j = 3; j <= i; j += 2) {
                sum = sum + 2 + j;
            }
            return sum;
        }
    }
}
