import java.util.*;
import java.lang.*;

class Solution {
    /**
     * Finds the lexicographically smallest path of length k in a grid.
     * 
     * Strategy:
     * To get the lexicographically smallest path, we must start with the smallest possible value,
     * which is 1. Since we can visit cells multiple times, the best strategy to keep the path 
     * lexicographically smallest is to oscillate between the cell containing 1 and its 
     * smallest neighbor.
     * 
     * For k = 1, the answer is [1].
     * For k > 1, the answer is [1, min_neighbor, 1, min_neighbor, ...].
     */
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int minNeighbor = Integer.MAX_VALUE;
        int startRow = -1, startCol = -1;

        // Find the position of the value 1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        // Find the smallest neighbor of the cell containing 1
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = startRow + dr[i];
            int nc = startCol + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                minNeighbor = Math.min(minNeighbor, grid.get(nr).get(nc));
            }
        }

        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans.add(1);
            } else {
                ans.add(minNeighbor);
            }
        }
        return ans;
    }
}
