import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> tri(int n) {
        if (n < 0) {
            return new ArrayList<>();
        }
        if (n == 0) {
            return new ArrayList<>(List.of(1));
        }

        // The sequence is defined as:
        // tri(0) = 1 (implied by example tri(3) = [1, 3, 2, 8])
        // tri(1) = 3
        // tri(n) = 1 + n / 2, if n is even
        // tri(n) = tri(n - 1) + tri(n - 2) + tri(n + 1), if n is odd

        // Note: For odd n, tri(n) depends on tri(n + 1).
        // Since n + 1 is even, tri(n + 1) = 1 + (n + 1) / 2.

        List<Integer> my_tri = new ArrayList<>();
        my_tri.add(1); // tri(0)

        for (int i = 1; i <= n; i++) {
            if (i == 1) {
                my_tri.add(3);
            } else if (i % 2 == 0) {
                my_tri.add(1 + i / 2);
            } else {
                // tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
                // tri(i+1) = 1 + (i+1)/2
                int tri_prev1 = my_tri.get(i - 1);
                int tri_prev2 = my_tri.get(i - 2);
                int tri_next = 1 + (i + 1) / 2;
                my_tri.add(tri_prev1 + tri_prev2 + tri_next);
            }
        }

        return my_tri;
    }
}
