import java.util.*;
import java.lang.*;

class Solution {
    public boolean isNested(String string) {
        List<Integer> opening_bracket_index = new ArrayList<>();
        List<Integer> closing_bracket_index = new ArrayList<>();

        for (int i = 0; i < string.length(); i++) {
            if (string.charAt(i) == '[') {
                opening_bracket_index.add(i);
            } else {
                closing_bracket_index.add(i);
            }
        }

        // To find the maximum number of valid pairs (subsequence), 
        // we pair the leftmost opening brackets with the rightmost closing brackets.
        Collections.reverse(closing_bracket_index);

        int pairs = 0;
        int closingIdx = 0;
        int totalClosing = closing_bracket_index.size();

        for (int openIdx : opening_bracket_index) {
            if (closingIdx < totalClosing && openIdx < closing_bracket_index.get(closingIdx)) {
                pairs++;
                closingIdx++;
            }
        }

        // A valid subsequence of brackets is nested if it contains at least 2 pairs.
        // For example, "[]" is 1 pair (not nested). "[[]]" is 2 pairs (nested).
        // Since the problem asks if there is a valid subsequence where at least one 
        // bracket is nested, this is equivalent to checking if we can form at least 2 pairs.
        return pairs >= 2;
    }
}
