import java.util.Stack;

public class Solution {
    /**
     * Checks if there is a valid subsequence of brackets where at least one bracket is nested.
     * A valid subsequence is nested if it contains the pattern "[[]]".
     * In terms of a balanced bracket sequence, nesting occurs if the maximum depth is 2 or more.
     */
    public boolean isNested(String string) {
        if (string == null || string.length() < 4) {
            return false;
        }

        int maxDepth = 0;
        int currentDepth = 0;

        // We need to find if there exists a valid balanced subsequence with depth >= 2.
        // A valid balanced subsequence exists if we can match pairs.
        // To check for nesting, we track the depth of the "best" possible balanced subsequence.
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < string.length(); i++) {
            char c = string.charAt(i);
            if (c == '[') {
                stack.push(i);
            } else if (c == ']') {
                if (!stack.isEmpty()) {
                    // We found a matching pair. 
                    // The depth of this pair is the number of open brackets currently in the stack.
                    int depth = stack.size();
                    if (depth >= 2) {
                        return true;
                    }
                    stack.pop();
                }
            }
        }

        return false;
    }
}
