class Solution {
    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }

        // Split by space to identify the last group of characters
        // -1 limit ensures trailing spaces are preserved as empty strings in the array
        String[] words = txt.split(" ", -1);
        String lastWord = words[words.length - 1];

        // The condition "is not a part of a word" implies the last character 
        // must be a standalone letter (a word of length 1).
        return lastWord.length() == 1 && Character.isLetter(lastWord.charAt(0));
    }
