public class Solution {
    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }

        int length = txt.length();
        char lastChar = txt.charAt(length - 1);

        // Check if the last character is an alphabetical letter
        if (!Character.isLetter(lastChar)) {
            return false;
        }

        // Check if it is not part of a word (meaning it must be preceded by a space or be the only char)
        if (length == 1) {
            return true;
        }

        char secondToLastChar = txt.charAt(length - 2);
        return secondToLastChar == ' ';
    }
}
