class Solution {
    public List<Integer> tri(int n) {
        if (n < 0) {
            return new ArrayList<>();
        }
        if (n == 0) {
            return new ArrayList<>(List.of(1));
        }

        List<Integer> my_tri = new ArrayList<>();
        // The problem defines tri(1) = 3. 
        // The example tri(3) = [1, 3, 2, 8] implies tri(0) = 1.
        my_tri.add(1); // tri(0)
        if (n >= 1) {
            my_tri.add(3); // tri(1)
        }

        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                // tri(n) = 1 + n / 2, if n is even.
                my_tri.add(1 + i / 2);
            } else {
                // tri(n) = tri(n - 1) + tri(n - 2) + tri(n + 1), if n is odd.
                // Since n is odd, n + 1 is even.
                // tri(n + 1) = 1 + (n + 1) / 2.
                int tri_n_minus_1 = my_tri.get(i - 1);
                int tri_n_minus_2 = my_tri.get(i - 2);
                int tri_n_plus_1 = 1 + (i + 1) / 2;
                my_tri.add(tri_n_minus_1 + tri_n_minus_2 + tri_n_plus_1);
            }
        }
        return my_tri;
    }
}
