import java.util.*;
import java.lang.*;

class Solution {
    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }
        // Split by space. Using -1 limit ensures trailing spaces are preserved as empty strings.
        String[] words = txt.split(" ", -1);
        String lastWord = words[words.length - 1];

        // The last character is a letter and not part of a word if the last "word" 
        // consists of exactly one character and that character is a letter.
        return lastWord.length() == 1 && Character.isLetter(lastWord.charAt(0));
    }
}
