public class Solution {
    /**
     * Evaluates whether the given number n can be written as the sum of exactly 4 positive even numbers.
     * The smallest positive even number is 2. 
     * Therefore, the smallest sum of 4 positive even numbers is 2 + 2 + 2 + 2 = 8.
     * Additionally, the sum of any number of even numbers is always even.
     * 
     * @param n the number to evaluate
     * @return true if n can be written as the sum of 4 positive even numbers, false otherwise.
     */
    public boolean isEqualToSumEven(int n) {
        // n must be at least 8 and must be even.
        return n >= 8 && n % 2 == 0;
    }
}
