class Solution {
    public String fixSpaces(String text) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        int n = text.length();

        while (i < n) {
            if (text.charAt(i) == ' ') {
                int count = 0;
                while (i < n && text.charAt(i) == ' ') {
                    count++;
                    i++;
                }
                if (count > 2) {
                    sb.append('-');
                } else {
                    for (int j = 0; j < count; j++) {
                        sb.append('_');
                    }
                }
            } else {
                sb.append(text.charAt(i));
                i++;
            }
        }

        return sb.toString();
    }
}
