import java.util.*;
import java.lang.*;

class Solution {
    public String filenameCheck(String file_name) {
        List<String> suf = Arrays.asList("txt", "exe", "dll");

        // Check if there is exactly one dot by splitting and checking length
        // Note: split("\\.") with a limit of -1 ensures trailing empty strings are kept
        String[] lst = file_name.split("\\.", -1);
        if (lst.length != 2) {
            return "No";
        }

        String prefix = lst[0];
        String extension = lst[1];

        // The substring before the dot should not be empty, and it starts with a letter
        if (prefix.isEmpty() || !Character.isLetter(prefix.charAt(0))) {
            return "No";
        }

        // The substring after the dot should be one of the allowed extensions
        if (!suf.contains(extension)) {
            return "No";
        }

        // There should not be more than three digits ('0'-'9') in the entire file's name
        long digitCount = file_name.chars().filter(Character::isDigit).count();
        if (digitCount > 3) {
            return "No";
        }

        return "Yes";
    }
}
