import java.util.*;

public class Solution {
    public String filenameCheck(String file_name) {
        // Check for exactly one dot
        int firstDotIndex = file_name.indexOf('.');
        int lastDotIndex = file_name.lastIndexOf('.');
        if (firstDotIndex == -1 || firstDotIndex != lastDotIndex) {
            return "No";
        }

        // Split into name and extension
        String namePart = file_name.substring(0, firstDotIndex);
        String extensionPart = file_name.substring(firstDotIndex + 1);

        // Substring before dot should not be empty and must start with a letter
        if (namePart.isEmpty()) {
            return "No";
        }
        char firstChar = namePart.charAt(0);
        if (!((firstChar >= 'a' && firstChar <= 'z') || (firstChar >= 'A' && firstChar <= 'Z'))) {
            return "No";
        }

        // Substring after dot must be one of ["txt", "exe", "dll"]
        List<String> validExtensions = Arrays.asList("txt", "exe", "dll");
        if (!validExtensions.contains(extensionPart)) {
            return "No";
        }

        // There should not be more than three digits in the entire file name
        int digitCount = 0;
        for (int i = 0; i < file_name.length(); i++) {
            char c = file_name.charAt(i);
            if (c >= '0' && c <= '9') {
                digitCount++;
            }
        }
        if (digitCount > 3) {
            return "No";
        }

        return "Yes";
    }
}
