class Solution {
    public boolean simplify(String x, String n) {
        String[] a = x.split("/");
        String[] b = n.split("/");

        // Use long to prevent overflow during multiplication
        long numX = Long.parseLong(a[0]);
        long denX = Long.parseLong(a[1]);
        long numN = Long.parseLong(b[0]);
        long denN = Long.parseLong(b[1]);

        long finalNumerator = numX * numN;
        long finalDenominator = denX * denN;

        // A fraction is a whole number if the numerator is divisible by the denominator
        return finalNumerator % finalDenominator == 0;
    }
}
