import java.util.*;

class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            return new ArrayList<>();
        }

        // We need to maintain the original index for stable sorting.
        // Java's Collections.sort() and List.sort() are stable, 
        // so we only need to provide a comparator for the digit sums.
        List<Integer> result = new ArrayList<>(nums);
        result.sort((a, b) -> Integer.compare(getDigitSum(a), getDigitSum(b)));
        return result;
    }

    private int getDigitSum(int n) {
        // The problem implies digit sum of the absolute value of the number.
        // Example: -11 -> 1+1 = 2, -12 -> 1+2 = 3.
        // Based on the example: [-1, -11, 1, -12, 11]
        // Sums: -1(1), -11(2), 1(1), -12(3), 11(2)
        // Sorted by sum: 1, 1, 2, 2, 3 -> [-1, 1, -11, 11, -12]
        // Wait, the example says: [-1, -11, 1, -12, 11]
        // Let's re-evaluate the example: 
        // 1 -> 1
        // 11 -> 2
        // -1 -> 1
        // -11 -> 2
        // -12 -> 3
        // Sorted by sum: (1, -1), (11, -11), (-12)
        // Stable sort: -1 comes before 1? No, 1 is index 0, -1 is index 2.
        // Let's look at the example again: orderByPoints([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
        // This suggests a specific logic for negative numbers.
        // If we treat the first digit of a negative number as negative:
        // 1: 1
        // 11: 1+1 = 2
        // -1: -1
        // -11: -1+1 = 0
        // -12: -1+2 = 1
        // Sums: -1(-1), -11(0), 1(1), -12(1), 11(2)
        // Sorted: -1, -11, 1, -12, 11. This matches the example perfectly.

        String s = String.valueOf(n);
        int sum = 0;
        int start = 0;
        if (s.charAt(0) == '-') {
            sum = -(s.charAt(1) - '0');
            start = 2;
        } else {
            sum = s.charAt(0) - '0';
            start = 1;
        }

        for (int i = start; i < s.length(); i++) {
            sum += (s.charAt(i) - '0');
        }
        return sum;
    }
}
