public class Solution {
    /**
     * Calculates the Brazilian factorial of n.
     * brazilian_factorial(n) = n! * (n-1)! * ... * 1!
     * 
     * @param n The input integer
     * @return The special factorial as a long
     */
    public long specialFactorial(int n) {
        long totalProduct = 1;
        long currentFactorial = 1;

        for (int i = 1; i <= n; i++) {
            currentFactorial *= i;
            totalProduct *= currentFactorial;
        }

        return totalProduct;
    }
}
