class Solution {
    public int getMaxTriples(int n) {
        // The sequence is a[i] = i^2 - i + 1 for i = 1 to n.
        // We need to find triples (a[i], a[j], a[k]) where i < j < k and (a[i] + a[j] + a[k]) % 3 == 0.
        // Let's analyze a[i] mod 3:
        // i = 1: 1^2 - 1 + 1 = 1 -> 1 mod 3
        // i = 2: 2^2 - 2 + 1 = 3 -> 0 mod 3
        // i = 3: 3^2 - 3 + 1 = 7 -> 1 mod 3
        // i = 4: 4^2 - 4 + 1 = 13 -> 1 mod 3
        // i = 5: 5^2 - 5 + 1 = 21 -> 0 mod 3
        // i = 6: 6^2 - 6 + 1 = 31 -> 1 mod 3
        // Pattern of a[i] mod 3: 1, 0, 1, 1, 0, 1, ...
        // Specifically:
        // If i % 3 == 0, a[i] = (3k)^2 - 3k + 1 = 9k^2 - 3k + 1 -> 1 mod 3
        // If i % 3 == 1, a[i] = (3k+1)^2 - (3k+1) + 1 = 9k^2 + 6k + 1 - 3k - 1 + 1 = 9k^2 + 3k + 1 -> 1 mod 3
        // If i % 3 == 2, a[i] = (3k+2)^2 - (3k+2) + 1 = 9k^2 + 12k + 4 - 3k - 2 + 1 = 9k^2 + 9k + 3 -> 0 mod 3

        // Let c0 be the count of elements where a[i] % 3 == 0
        // Let c1 be the count of elements where a[i] % 3 == 1
        // Let c2 be the count of elements where a[i] % 3 == 2

        // From the analysis:
        // a[i] % 3 is 0 if i % 3 == 2
        // a[i] % 3 is 1 if i % 3 == 0 or i % 3 == 1
        // a[i] % 3 is never 2.

        long c0 = 0;
        long c1 = 0;

        for (int i = 1; i <= n; i++) {
            if (i % 3 == 2) {
                c0++;
            } else {
                c1++;
            }
        }

        // We need (a[i] + a[j] + a[k]) % 3 == 0.
        // Possible combinations of (mod 3) values:
        // 1. (0, 0, 0) -> c0C3
        // 2. (1, 1, 1) -> c1C3
        // 3. (0, 1, 2) -> Not possible since c2 = 0
        // 4. (0, 0, 1) -> Sum is 1 (No)
        // 5. (1, 1, 0) -> Sum is 2 (No)

        long result = 0;

        // Combinations of 3 from c0
        if (c0 >= 3) {
            result += (c0 * (c0 - 1) * (c0 - 2)) / 6;
        }

        // Combinations of 3 from c1
        if (c1 >= 3) {
            result += (c1 * (c1 - 1) * (c1 - 2)) / 6;
        }

        return (int) result;
    }
}
