import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            return new ArrayList<>();
        }

        // We use a custom object or a stream of indices to maintain stability 
        // and access the original index for the tie-breaking rule.
        return IntStream.range(0, nums.size())
                .boxed()
                .sorted((i, j) -> {
                    int sumI = getDigitSum(nums.get(i));
                    int sumJ = getDigitSum(nums.get(j));
                    if (sumI != sumJ) {
                        return Integer.compare(sumI, sumJ);
                    }
                    // If sums are equal, order by original index (ascending)
                    return Integer.compare(i, j);
                })
                .map(nums::get)
                .collect(Collectors.toList());
    }

    private int getDigitSum(int n) {
        // Use absolute value to handle negative numbers as per the example
        // Example: -11 -> 1+1 = 2
        String s = String.valueOf(Math.abs((long) n));
        int sum = 0;
        for (char c : s.toCharArray()) {
            sum += Character.getNumericValue(c);
        }
        return sum;
    }
}
