import java.util.*;

class Solution {
    public List<String> bf(String planet1, String planet2) {
        // The list of planets in order of proximity to the Sun
        List<String> planet_names = Arrays.asList("Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune");

        // Check if both planet names are valid
        if (!planet_names.contains(planet1) || !planet_names.contains(planet2)) {
            return Collections.emptyList();
        }

        // If the planets are the same, there are no planets between them
        if (planet1.equals(planet2)) {
            return Collections.emptyList();
        }

        int index1 = planet_names.indexOf(planet1);
        int index2 = planet_names.indexOf(planet2);

        int start = Math.min(index1, index2);
        int end = Math.max(index1, index2);

        // subList(fromIndex, toIndex) returns elements from fromIndex (inclusive) to toIndex (exclusive)
        // We want elements between the two indices, so we start at start + 1 and end at end.
        return new ArrayList<>(planet_names.subList(start + 1, end));
    }
}
