import java.util.*;

class Solution {
    public int getMaxTriples(int n) {
        // The problem asks for the number of triples (a[i], a[j], a[k]) where i < j < k
        // and (a[i] + a[j] + a[k]) % 3 == 0.
        // a[i] = i*i - i + 1.
        // Let's analyze a[i] mod 3:
        // i = 1: 1*1 - 1 + 1 = 1. 1 % 3 = 1.
        // i = 2: 2*2 - 2 + 1 = 3. 3 % 3 = 0.
        // i = 3: 3*3 - 3 + 1 = 7. 7 % 3 = 1.
        // i = 4: 4*4 - 4 + 1 = 13. 13 % 3 = 1.
        // i = 5: 5*5 - 5 + 1 = 21. 21 % 3 = 0.
        // i = 6: 6*6 - 6 + 1 = 31. 31 % 3 = 1.
        // Pattern of a[i] % 3 for i = 1, 2, 3, 4, 5, 6... is 1, 0, 1, 1, 0, 1...
        // Specifically:
        // If i % 3 == 0, a[i] = (3k)^2 - 3k + 1 = 9k^2 - 3k + 1 -> a[i] % 3 = 1.
        // If i % 3 == 1, a[i] = (3k+1)^2 - (3k+1) + 1 = 9k^2 + 6k + 1 - 3k - 1 + 1 = 9k^2 + 3k + 1 -> a[i] % 3 = 1.
        // If i % 3 == 2, a[i] = (3k+2)^2 - (3k+2) + 1 = 9k^2 + 12k + 4 - 3k - 2 + 1 = 9k^2 + 9k + 3 -> a[i] % 3 = 0.

        // So, a[i] % 3 is 0 if i % 3 == 2, and 1 if i % 3 == 0 or 1.
        // Let c0 be the count of elements where a[i] % 3 == 0.
        // Let c1 be the count of elements where a[i] % 3 == 1.
        // Let c2 be the count of elements where a[i] % 3 == 2.

        // From our analysis:
        // c0 = count of i in [1, n] such that i % 3 == 2.
        // c1 = count of i in [1, n] such that i % 3 == 0 or 1.
        // c2 = 0 (since a[i] % 3 is never 2).

        long c0 = (n >= 2) ? (n - 2) / 3 + 1 : 0;
        long c1 = n - c0;

        // We need (a[i] + a[j] + a[k]) % 3 == 0.
        // Possible combinations of (rem_i, rem_j, rem_k) that sum to 0 mod 3:
        // 1. (0, 0, 0) -> Combination(c0, 3)
        // 2. (1, 1, 1) -> Combination(c1, 3)
        // 3. (0, 1, 2) -> c0 * c1 * c2 (but c2 is 0)

        long result = 0;
        if (c0 >= 3) {
            result += (c0 * (c0 - 1) * (c0 - 2)) / 6;
        }
        if (c1 >= 3) {
            result += (c1 * (c1 - 1) * (c1 - 2)) / 6;
        }

        return (int) result;
    }
}
