import java.math.BigInteger;

public class Solution {
    /**
     * Simplifies the expression x * n and returns true if the result is a whole number.
     * 
     * @param x String representation of a fraction "numerator/denominator"
     * @param n String representation of a fraction "numerator/denominator"
     * @return true if the product is a whole number, false otherwise.
     */
    public boolean simplify(String x, String n) {
        // Split the input strings to extract numerators and denominators
        String[] xParts = x.split("/");
        String[] nParts = n.split("/");

        // Use BigInteger to prevent overflow for large input values
        BigInteger xNum = new BigInteger(xParts[0]);
        BigInteger xDen = new BigInteger(xParts[1]);
        BigInteger nNum = new BigInteger(nParts[0]);
        BigInteger nDen = new BigInteger(nParts[1]);

        // The product of two fractions (a/b) * (c/d) is (a * c) / (b * d)
        BigInteger finalNumerator = xNum.multiply(nNum);
        BigInteger finalDenominator = xDen.multiply(nDen);

        // A fraction is a whole number if the numerator is divisible by the denominator
        // remainder() returns 0 if finalNumerator is perfectly divisible by finalDenominator
        return finalNumerator.remainder(finalDenominator).equals(BigInteger.ZERO);
    }
}
