import java.util.*;
import java.lang.*;

class Solution {
    public List<String> bf(String planet1, String planet2) {
        List<String> planet_names = Arrays.asList("Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune");

        if (!planet_names.contains(planet1) || !planet_names.contains(planet2)) {
            return new ArrayList<>();
        }

        int planet1_index = planet_names.indexOf(planet1);
        int planet2_index = planet_names.indexOf(planet2);

        int start = Math.min(planet1_index, planet2_index);
        int end = Math.max(planet1_index, planet2_index);

        // If planets are adjacent or the same, subList will be empty
        if (end - start <= 1) {
            return new ArrayList<>();
        }

        // subList returns a view; we wrap it in a new ArrayList to ensure it's a standalone list
        return new ArrayList<>(planet_names.subList(start + 1, end));
    }
}
