import java.lang.*;

class Solution {
    public List<String> listSort(List<String> lst) {
        List<String> filteredList = new ArrayList<>();

        // First, filter out strings with odd lengths
        for (String s : lst) {
            if (s.length() % 2 == 0) {
                filteredList.add(s);
            }
        }

        // Sort the list:
        // 1. Primary sort: Ascending by length
        // 2. Secondary sort: Alphabetically (natural order)
        Collections.sort(filteredList, new Comparator<String>() {
            @Override
            public int compare(String s1, String s2) {
                if (s1.length() != s2.length()) {
                    return Integer.compare(s1.length(), s2.length());
                }
                return s1.compareTo(s2);
            }
        });

        return filteredList;
    }
}
