import java.util.*;

public class Solution {
    public List<String> bf(String planet1, String planet2) {
        List<String> planets = Arrays.asList(
            "Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"
        );

        int index1 = planets.indexOf(planet1);
        int index2 = planets.indexOf(planet2);

        // Return empty list if either planet name is invalid
        if (index1 == -1 || index2 == -1) {
            return new ArrayList<>();
        }

        int start = Math.min(index1, index2);
        int end = Math.max(index1, index2);

        List<String> result = new ArrayList<>();
        // Get planets strictly between the two indices
        for (int i = start + 1; i < end; i++) {
            result.add(planets.get(i));
        }

        // If planet1 was further from the sun than planet2, 
        // the problem asks for sorting by proximity to the sun, 
        // which the loop above already handles by iterating from start to end.
        return result;
    }
}
