public class Solution {
    public int doubleTheDifference(List<Object> lst) {
        if (lst == null || lst.isEmpty()) {
            return 0;
        }

        int sum = 0;
        for (Object obj : lst) {
            if (obj instanceof Integer) {
                int num = (Integer) obj;
                if (num >= 0 && num % 2 != 0) {
                    sum += num * num;
                }
            }
        }
        return sum;
    }
}
