import java.util.*;
import java.lang.*;

class Solution {
    public String StrongestExtension(String class_name, List<String> extensions) {
        if (extensions == null || extensions.isEmpty()) {
            return class_name;
        }

        String strongest = extensions.get(0);
        int maxStrength = calculateStrength(strongest);

        for (int i = 1; i < extensions.size(); i++) {
            String current = extensions.get(i);
            int currentStrength = calculateStrength(current);
            if (currentStrength > maxStrength) {
                maxStrength = currentStrength;
                strongest = current;
            }
        }

        return class_name + "." + strongest;
    }

    private int calculateStrength(String s) {
        int cap = 0;
        int sm = 0;
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) {
                cap++;
            } else if (Character.isLowerCase(c)) {
                sm++;
            }
        }
        return cap - sm;
    }
}
