import java.util.*;
import java.lang.*;

class Solution {
    public boolean cycpatternCheck(String a, String b) {
        int n = a.length();
        int m = b.length();

        if (m == 0) return true;
        if (m > n) return false;

        // A rotation of string b is any substring of length m in (b + b)
        // However, we only need to check rotations of b against substrings of a.
        String doubleB = b + b;

        // Iterate through all possible substrings of a with length m
        for (int i = 0; i <= n - m; i++) {
            String subA = a.substring(i, i + m);
            // If this substring of a is found within b + b, it is a rotation of b
            if (doubleB.contains(subA)) {
                return true;
            }
        }

        return false;
    }
}
