public class Solution {
    /**
     * Compares the actual game scores with the guessed scores.
     * Returns a list containing the absolute difference for each match.
     *
     * @param game  The list of actual scores.
     * @param guess The list of guessed scores.
     * @return A list of absolute differences between game and guess.
     */
    public List<Integer> compare(List<Integer> game, List<Integer> guess) {
        List<Integer> result = new ArrayList<>(game.size());
        for (int i = 0; i < game.size(); i++) {
            int diff = Math.abs(game.get(i) - guess.get(i));
            result.add(diff);
        }
        return result;
    }
}
