public class Solution {
    public String StrongestExtension(String class_name, List<String> extensions) {
        if (extensions == null || extensions.isEmpty()) {
            return class_name;
        }

        String strongestExt = "";
        int maxStrength = Integer.MIN_VALUE;

        for (String ext : extensions) {
            int cap = 0;
            int sm = 0;
            for (int i = 0; i < ext.length(); i++) {
                char c = ext.charAt(i);
                if (Character.isUpperCase(c)) {
                    cap++;
                } else if (Character.isLowerCase(c)) {
                    sm++;
                }
            }

            int currentStrength = cap - sm;

            // We use > instead of >= to ensure that if strengths are equal, 
            // the one that appeared first in the list is kept.
            if (currentStrength > maxStrength) {
                maxStrength = currentStrength;
                strongestExt = ext;
            }
        }

        return class_name + "." + strongestExt;
    }
}
