import java.util.*;
import java.lang.*;

class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        // A right-angled triangle must satisfy the Pythagorean theorem: a^2 + b^2 = c^2
        // Since the sides are not necessarily sorted, we must check all three possibilities
        // for which side is the hypotenuse.
        long a2 = (long) a * a;
        long b2 = (long) b * b;
        long c2 = (long) c * c;

        return (a2 + b2 == c2) || (a2 + c2 == b2) || (b2 + c2 == a2);
    }
}
