class Solution {
    public int doubleTheDifference(List<Object> lst) {
        if (lst == null || lst.isEmpty()) {
            return 0;
        }
        return lst.stream()
                .filter(i -> i instanceof Integer)
                .map(i -> (Integer) i)
                .filter(i -> i >= 0 && i % 2 != 0)
                .map(i -> i * i)
                .reduce(0, Integer::sum);
