import java.util.*;

class Solution {
    public String findMax(List<String> words) {
        if (words == null || words.isEmpty()) {
            return "";
        }

        List<String> words_sort = new ArrayList<>(words);
        words_sort.sort(new Comparator<String>() {
            @Override
            public int compare(String o1, String o2) {
                Set<Character> s1 = new HashSet<>();
                for (char ch : o1.toCharArray()) {
                    s1.add(ch);
                }
                Set<Character> s2 = new HashSet<>();
                for (char ch : o2.toCharArray()) {
                    s2.add(ch);
                }

                int size1 = s1.size();
                int size2 = s2.size();

                if (size1 != size2) {
                    return Integer.compare(size1, size2);
                } else {
                    // If unique counts are equal, we want the lexicographically smaller one 
                    // to be considered "greater" so it ends up at the end of the sorted list.
                    return o2.compareTo(o1);
                }
            }
        });

        return words_sort.get(words_sort.size() - 1);
    }
}
