import java.util.*;

class Solution {
    public String findMax(List<String> words) {
        if (words == null || words.isEmpty()) {
            return "";
        }

        String result = null;
        int maxUnique = -1;

        for (String word : words) {
            int currentUnique = countUniqueCharacters(word);

            if (currentUnique > maxUnique) {
                maxUnique = currentUnique;
                result = word;
            } else if (currentUnique == maxUnique) {
                if (result == null || word.compareTo(result) < 0) {
                    result = word;
                }
            }
        }

        return result;
    }

    private int countUniqueCharacters(String s) {
        Set<Character> set = new HashSet<>();
        for (char c : s.toCharArray()) {
            set.add(c);
        }
        return set.size();
    }
}
