import java.util.ArrayList;
import java.util.List;

public class Solution {
    /**
     * Calculates the total carrots eaten and the remaining carrots in stock.
     * 
     * @param number    The number of carrots already eaten.
     * @param need      The number of carrots the rabbit needs to eat.
     * @param remaining The number of carrots available in stock.
     * @return A list containing [total eaten, remaining in stock].
     */
    public List<Integer> eat(int number, int need, int remaining) {
        // Determine how many carrots the rabbit actually eats from the stock.
        // If need is greater than remaining, the rabbit eats all remaining carrots.
        int eatenFromStock = Math.min(need, remaining);

        int totalEaten = number + eatenFromStock;
        int leftInStock = remaining - eatenFromStock;

        List<Integer> result = new ArrayList<>();
        result.add(totalEaten);
        result.add(leftInStock);

        return result;
    }
}
