            }
        }

        // Step 2: Handle Multiplication (*) and Division (/)
        List<String> ops2 = new ArrayList<>(ops1);
        List<Integer> nums2 = new ArrayList<>(nums1);

        for (int i = 0; i < ops2.size(); ) {
