            if (op.equals("*") || op.equals("/")) {
                int left = nums2.get(i);
                int right = nums2.get(i + 1);
                int result = op.equals("*") ? left * right : left / right;

                nums2.set(i, result);
                nums2.remove(i + 1);
                ops2.remove(i);
            } else {
                i++;
            }
        }

        // Step 3: Handle Addition (+) and Subtraction (-)
