        for (int i = 0; i < ops2.size(); i++) {
            String op = ops2.get(i);
            int nextVal = nums2.get(i + 1);
            if (op.equals("+")) {
                finalResult += nextVal;
            } else if (op.equals("-")) {
                finalResult -= nextVal;
            }
        }

