import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> generateIntegers(int a, int b) {
        int lower = Math.min(a, b);
        int upper = Math.max(a, b);

        List<Integer> result = new ArrayList<>();
        // The problem asks for even digits (2, 4, 6, 8) between a and b.
        // We iterate through the possible even digits and check if they fall within the range.
        for (int i = 2; i <= 8; i += 2) {
            if (i >= lower && i <= upper) {
                result.add(i);
            }
        }
        return result;
    }
}
